package com.tihai.controller;
import com.tihai.utils.*;import com.tihai.common.R;import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.annotation.Autowired;import java.util.*;import java.util.concurrent.*;import java.nio.file.*;import java.io.*;
@RestController @RequestMapping("/local/yuketang") public class RainController {
 @Autowired AccountRegistry registry;@Autowired RainStore store;@Autowired DeepSeekClient ai;@Autowired ReviewStore review;@Autowired SecurityAlertHub security;
 private final Map<String,Session> sessions=new ConcurrentHashMap<>();private final ExecutorService workers=Executors.newCachedThreadPool();
 protected ExamBrowserSession open(String account)throws IOException{return new ExamBrowserSession.ProcessSession(Paths.get("D:/tool/qita/SuperAutoStudy"),"rain-"+account,"yuketang-bridge.cjs");}
 private String account(){if(!"yuketang".equals(AccountScope.platform())||AccountScope.id().isEmpty())throw new IllegalStateException("请先添加并切换到雨课堂账号");return AccountScope.id();}
 private class Session {
  final String account;final ExamBrowserSession browser;final Map<String,CompletableFuture<Map<String,Object>>> replies=new ConcurrentHashMap<>();volatile String task="";volatile boolean closed;
  Session(String a)throws Exception{account=a;browser=open(a);workers.submit(()->{try{while(!closed){Map<String,Object> e=browser.read();String event=String.valueOf(e.get("event"));if("response".equals(event)){CompletableFuture<Map<String,Object>> f=replies.remove(String.valueOf(e.get("requestId")));if(f!=null)f.complete(e);}else if("ai_request".equals(event)){workers.submit(()->answer(e));}else process(e);}}catch(Exception ex){closed=true;for(CompletableFuture f:replies.values())f.completeExceptionally(new IOException("雨课堂窗口已关闭，请重新打开登录窗口"));if(!task.isEmpty())try{store.update(task,account,changes("state","stopped","message","浏览器已关闭；请核对平台后继续"));}catch(Exception ignored){}}});}
  Map<String,Object> command(String op,Map<String,Object> b)throws Exception{if(closed)throw new IOException("雨课堂会话已关闭，请重新打开登录窗口");Map<String,Object> c=new LinkedHashMap<>(b);String id=UUID.randomUUID().toString();c.put("op",op);c.put("requestId",id);CompletableFuture<Map<String,Object>> f=new CompletableFuture<>();replies.put(id,f);try{browser.send(c);Map r=f.get(65,TimeUnit.SECONDS);if(!Boolean.TRUE.equals(r.get("ok")))throw new IOException(String.valueOf(r.get("message")));return (Map<String,Object>)r.get("data");}finally{replies.remove(id);}}
  void answer(Map<String,Object> e){Map<String,Object> response=new LinkedHashMap<>();response.put("op","ai_result");response.put("requestId",e.get("requestId"));try{String id=String.valueOf(e.get("taskId"));Map t=store.task(id,account);if(!id.equals(task)||!Boolean.TRUE.equals(t.get("autoAI")))throw new IOException("此任务未启用AI");response.put("answer",ai.rainAnswer(String.valueOf(e.get("text")),((Number)e.getOrDefault("optionCount",0)).intValue()));}catch(Exception ex){response.put("error",ex instanceof IOException?ex.getMessage():"AI参考答案暂不可用");}try{browser.send(response);}catch(Exception ignored){}}
  void process(Map<String,Object> e)throws Exception{String id=String.valueOf(e.get("taskId"));if(!id.equals(task))return;String kind=String.valueOf(e.get("event"));if("questions".equals(kind)){archive(id,account,(List)e.get("questions"));return;}Map<String,Object> update=new LinkedHashMap<>(e);String state="progress".equals(kind)?"running":"verification".equals(kind)?"verification":"ready".equals(kind)?"ready":"completed".equals(kind)?"completed":"stopped".equals(kind)?"stopped":"ready_for_review".equals(kind)||"manual".equals(kind)?"manual":"failed";update.put("state",state);if("verification".equals(kind)){update.put("message","平台提示需要人工处理，请打开平台窗口");security.raise("yuketang",account+":"+id,String.valueOf(store.task(id,account).get("title")),String.valueOf(update.get("message")));}else security.resolve("yuketang",account+":"+id);if("ready".equals(kind))update.put("message",String.valueOf(e.getOrDefault("pendingLabel","答案已选好，等待你确认提交")));if("manual".equals(state)&&!e.containsKey("message"))update.put("message","脚本轮次结束，请核对平台各任务点；未按课程满进度认定完成");store.update(id,account,update);if("completed".equals(state)||"failed".equals(state)){task="";workers.submit(()->{try{command("stop",Collections.emptyMap());}catch(Exception ignored){}});}}
  void close(){closed=true;browser.close();}
 }
 static Map<String,Object> changes(Object... kv){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<kv.length;i+=2)m.put(String.valueOf(kv[i]),kv[i+1]);return m;}
 private Session session(String a)throws IOException{Session s=sessions.get(a);if(s==null||s.closed)throw new IOException("请先打开雨课堂登录窗口");return s;}
 @PostMapping("/accounts/add")public R add(@RequestBody Map<String,String> b){try{return R.ok("已创建独立账号空间，请打开登录窗口").setData(registry.addRain(b.get("label"),b.get("entry")));}catch(Exception e){return R.error(400,e.getMessage());}}
 @PostMapping("/login")public synchronized R login(){try{String a=account();Session existing=sessions.get(a);if(existing!=null&&!existing.closed){existing.command("focus",Collections.emptyMap());return R.ok("已打开此账号的平台窗口");}Map info=registry.lookup(a);Session s=new Session(a);sessions.put(a,s);String pf=System.getenv("ProgramFiles(x86)");try{s.command("init",changes("accountId",a,"url",info.get("entry"),"edge",Paths.get(pf==null?"C:/Program Files (x86)":pf,"Microsoft/Edge/Application/msedge.exe").toString()));}catch(Exception e){s.close();sessions.remove(a);throw e;}return R.ok("请在独立窗口登录，然后点击学生通中的确认已登录");}catch(Exception e){return R.error(400,e.getMessage());}}
 @PostMapping("/login/confirm")public R confirm(){try{String a=account();Map info=session(a).command("confirm",Collections.emptyMap());registry.verified(a,String.valueOf(info.get("identity")));return R.ok("已确认登录会话；账号数据独立保存");}catch(Exception e){return R.error(400,e.getMessage());}}
 @GetMapping("/courses")public R courses(){try{return R.ok().setData(session(account()).command("courses",Collections.emptyMap()));}catch(Exception e){return R.error(400,e.getMessage());}}
 @GetMapping("/current")public R current(){try{return R.ok().setData(session(account()).command("current",Collections.emptyMap()));}catch(Exception e){return R.error(400,e.getMessage());}}
 @GetMapping("/tasks")public R list(@RequestParam(defaultValue="chapters")String module){try{return R.ok().setData(changes("items",store.list(account(),module),"message","当前雨课堂账号的"+("chapters".equals(module)?"章节":"homework".equals(module)?"作业":"考试")+"任务 · 网页读题适配尚待真实账号验证"));}catch(Exception e){return R.ok().setData(changes("items",Collections.emptyList(),"message",e.getMessage()));}}
 @PostMapping("/tasks/add")public R addTask(@RequestBody Map<String,String> b){try{String a=account();Map t=store.add(a,b.get("title"),b.get("url"),b.getOrDefault("module","chapters"));registry.attachTask(String.valueOf(t.get("id")),a);review.course(String.valueOf(t.get("id")),String.valueOf(t.get("title")));return R.ok("任务已添加，尚未开始").setData(t);}catch(Exception e){return R.error(400,e.getMessage());}}
 @PostMapping("/tasks/start")public synchronized R start(@RequestBody Map<String,Object> b){String a=account(),id=String.valueOf(b.get("id"));try{Map t=store.task(id,a);if(!Boolean.TRUE.equals(registry.lookup(a).get("verified")))return R.error(400,"请先确认当前雨课堂账号已登录");Session s=session(a);if(!s.task.isEmpty())return R.error(409,"此账号已有浏览器任务，请先停止；其他账号不受影响");boolean auto=Boolean.TRUE.equals(b.get("autoAI")),submit=Boolean.TRUE.equals(b.get("autoSubmit"));if(submit&&!Boolean.TRUE.equals(b.get("confirmed")))return R.error(400,"自动提交需要明确确认");store.update(id,a,changes("state","starting","autoAI",auto,"autoSubmit",submit,"message","正在打开此账号的课程窗口"));s.task=id;s.command("start",changes("taskId",id,"url",t.get("url"),"module",t.get("module"),"autoAI",auto,"autoSubmit",submit));return R.ok("已开始，状态以平台实际回执为准");}catch(Exception e){try{Session s=sessions.get(a);if(s!=null&&id.equals(s.task)){s.command("stop",Collections.emptyMap());s.task="";}store.update(id,a,changes("state","failed","message",e.getMessage()));}catch(Exception ignored){}return R.error(400,e.getMessage());}}
 @PostMapping("/tasks/stop")public synchronized R stop(@RequestBody Map<String,String> b){try{String a=account(),id=b.get("id");store.task(id,a);Session s=session(a);if(!id.equals(s.task))return R.error(409,"该任务未在此账号运行");s.command("stop",Collections.emptyMap());s.task="";store.update(id,a,changes("state","stopped","message","已停止；已发送的提交无法撤回"));security.resolve("yuketang",a+":"+id);return R.ok("已停止此账号的任务");}catch(Exception e){return R.error(400,e.getMessage());}}
 @PostMapping("/tasks/delete")public R delete(@RequestBody Map<String,String> b){try{store.delete(b.get("id"),account());return R.ok("任务已删除，已收录复习题目保留");}catch(Exception e){return R.error(400,e.getMessage());}}
 @PostMapping("/tasks/submit")public R submit(@RequestBody Map<String,Object> b){try{String a=account(),id=String.valueOf(b.get("id"));Map t=store.task(id,a);if(!"ready".equals(t.get("state"))||!Boolean.TRUE.equals(b.get("confirmed")))return R.error(409,"没有等待确认的本题答案");session(a).command("submit",changes("taskId",id));return R.ok("已确认当前题目提交，请等待平台回执");}catch(Exception e){return R.error(400,e.getMessage());}}
 private void archive(String id,String a,List<Map<String,Object>> rows)throws Exception{Map t=store.task(id,a);registry.attachTask(id,a);review.course(id,String.valueOf(t.get("title")));for(Map<String,Object> q:rows){String type=String.valueOf(q.get("type")),answer=String.valueOf(q.getOrDefault("platformAnswer",""));try{String canonical=ReviewParser.canonical(type,answer,(List<String>)q.get("options"));q.put("canonicalAnswer",canonical);q.put("gradeable",!canonical.isEmpty()&&!Boolean.TRUE.equals(q.get("needsVision")));}catch(Exception e){q.put("gradeable",false);q.put("canonicalAnswer","");}q.put("studentAnswer","");}review.add(id,"homework".equals(t.get("module"))?"作业":"exams".equals(t.get("module"))?"考试":"章节小测",String.valueOf(t.get("title")),id,rows,0);}
 @PostMapping("/review/collect")public R collect(@RequestBody Map<String,String> b){try{String a=account(),id=b.get("course");Map t=store.task(id,a);Session s=session(a);if(!id.equals(s.task))return R.error(409,"请先打开对应任务后收录当前页面题目");Map data=s.command("collect",Collections.emptyMap());List<Map<String,Object>> rows=(List)data.get("questions");if(rows.isEmpty())return R.error(400,"当前页面未识别到完整题目，未伪造题目或答案");archive(id,a,rows);return R.ok("已收录当前页面 "+rows.size()+" 题；未作答、未提交");}catch(Exception e){return R.error(400,e.getMessage());}}
 @javax.annotation.PreDestroy public void close(){for(Session s:sessions.values())s.close();workers.shutdownNow();try{workers.awaitTermination(5,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}}
}
